from lib import *
S = SS('j262')
steps = [
    step("ProcessHandle.current() 与 info()(macOS,JDK 21.0.12):pid、isAlive、supportsNormalTermination = true;info.command = …/java,commandLine 是完整的 java -cp out Main info,arguments 是 [-cp, out, Main, info],startInstant 有值,totalCpuDuration 31 ms,user = w;parent 是启动它的 Python 进程。对当前进程 destroy() 抛 IllegalStateException(destroy of current process not allowed)。allProcesses().count() = 742 个,用时 1 ms;对每个进程调用 info():只有 454 / 742 个有 command,用时 21 ms——没有权限的进程拿不到命令。", t=tl(S(1)), done=lidx(S(1), 'pid = ', 'info.command', 'info.commandLine', 'info.arguments'), mark=lidx(S(1), 'info.startInstant', 'parent = ', 'destroy of current process', 'allProcesses().count()', 'info():有 command'), kv=KV([['当前进程的 info', 'command / commandLine / arguments / user 都有值'], ['allProcesses()', '742 个进程,1 ms;只有 454 个能读到 command']], ['allProcesses()'])),
    step("children() 只返回直接子进程,descendants() 包含孙进程:父 shell 启动了 sleep 61、sleep 62 和一个 bash -c 'sleep 63 & wait'。children() 是 3 个(含那个 bash),descendants() 是 4 个(还有它的子进程 sleep 63)。只对父 shell destroyForcibly:父进程死了,原来的 4 个后代仍然全部存活,3 个直接子进程的 parent 变成 pid 1(launchd),孙进程的 parent 仍然是那个 bash;逐个 destroyForcibly 之后存活 0 个。杀掉父进程不会杀掉它的子进程。", t=tl(S(2)), done=lidx(S(2), '父 shell', 'children()', 'descendants() 共 4 个'), mark=lidx(S(2), 'destroyForcibly 只杀父 shell 之后', '逐个 destroyForcibly 之后'), kv=KV([['children()', '3 个直接子进程'], ['descendants()', '4 个(含孙进程)'], ['只杀父进程后', '4 个后代全部存活,直接子进程变成 pid 1 的子进程']], ['只杀父进程后'])),
    step("onExit() 的完成时机:子进程 sleep 1 在 993 ms 时完成,isAlive = false,exitValue = 0;一个非子进程(由已退出的 shell 派生,parent = pid 1)用 ProcessHandle.of(pid) 也能得到 onExit(),在 1019 ms 时完成。10 次 sleep 0.3 的 onExit 延迟是 303–313 ms,中位数 310 ms,也就是进程退出之后约 3–13 ms 就能得到通知。进程退出后 ProcessHandle.of(pid) 是 Optional.empty。", t=tl(S(3)), done=lidx(S(3), '子进程 sleep 1', '非子进程'), mark=lidx(S(3), '它的 onExit() 完成', '10 次 sleep 0.3', 'ProcessHandle.of(pid)'), b=bars([['sleep 1 的子进程', 993, '993 ms'], ['非子进程 sleep 1', 1019, '1019 ms'], ['10 次 sleep 0.3 中位数', 310, '310 ms']], 1020, done=[0, 1, 2]), kv=KV([['子进程', 'onExit 在进程退出后约 0–13 ms 完成'], ['非子进程', '也可以 onExit(1019 ms)'], ['已退出的 pid', 'ProcessHandle.of 为 Optional.empty']], ['非子进程'])),
    step("destroy() 与 destroyForcibly():对一个忽略 SIGTERM(trap '' TERM)的进程,destroy() 返回 true——只表示请求已发出——1.5 s 后 isAlive 仍是 true;destroyForcibly() 返回 true,waitFor 得到退出码 137(= 128 + 9,SIGKILL),1 ms 内进程消失。普通 sleep 30 被 destroy() 的退出码是 143(= 128 + 15,SIGTERM)。对已退出的进程再次 destroy() 或 destroyForcibly() 返回 false;对 pid 1 destroy() 返回 false(没有权限)。destroy() 的返回值不能当成“进程已经停了”。", t=tl(S(4)), done=lidx(S(4), '忽略 SIGTERM 的进程', 'destroyForcibly() 返回 true'), mark=lidx(S(4), '普通 sleep 30 被 destroy()', '对已退出的进程再次', '对 pid 1', '清理检查'), kv=KV([['destroy()(SIGTERM)', '返回 true,但忽略 TERM 的进程 1.5 s 后仍存活'], ['destroyForcibly()(SIGKILL)', '退出码 137,1 ms 内结束'], ['普通 sleep 被 destroy()', '退出码 143']], ['destroy()(SIGTERM)'])),
]
A = mkartj('j262', 262, 'Java,进程,ProcessHandle,destroy,onExit,descendants,真实验证,动画演示',
    '在 JDK 21 / macOS 上实测 ProcessHandle:info() 能读到命令与 CPU 时间但只有 454 / 742 个进程有 command;descendants() 比 children() 多孙进程,只杀父进程后 4 个后代全部存活并改挂到 pid 1;onExit() 对非子进程也有效,延迟约 3–13 ms;destroy() 返回 true 但忽略 SIGTERM 的进程仍然活着,destroyForcibly 得到退出码 137。',
    'ProcessHandle 让 Java 能观察和管理任意进程,不只是自己启动的子进程。这篇用真实的进程树量出它能读到什么、怎么遍历、通知有多快,以及 destroy 与 destroyForcibly 的真实含义。',
    [('454 / 742', 'allProcesses() 里能读到 info().command 的进程数(没有权限的进程为空)'), ('4 / 4', '只 destroyForcibly 父 shell 之后仍然存活的后代数'), ('137', '忽略 SIGTERM 的进程被 destroyForcibly 之后 waitFor 的退出码(destroy() 之后 1.5 s 仍然存活)')],
    [('当前进程与 info', None), ('children 与 descendants', None), ('onExit', None), ('destroy 与 destroyForcibly', None)],
    steps, [ENV_J + '。JDK 21.0.12,macOS arm64(info() 的字段可用性与权限是平台相关的,Linux 与 Windows 不同);进程是 sleep、sh 与 bash 小程序', '没有验证:Linux 的 /proc 实现与权限差异、Windows 上 destroy() 的语义(没有 SIGTERM)、pid 回收(onExit 对 pid 被复用的进程)、容器里的 PID namespace、ProcessHandle 与 ProcessBuilder.Redirect 的结合(下一篇)'], 'ProcessHandle')
